from melite_models import  KnobRow,Model, Cell, LaneInputs, Quant, Variant, Genre, ClipType


class Anima(Model):
    id = 'anima'
    genre = Genre.IMAGE
    label = 'Anima'
    description = 'Anime/illustration text-to-image. Cosmos-Predict2 base with Danbooru-style prompting.'
    form = 'form_generate'
    engine = 'comfyui'
    card = 'image-gen'           # the owning card (cross-validation hook)
    # No mods — no lora catalog for this family today (mods are
    # model-level declarations; the loras channel is closed).
    # field defaults (merged_defaults base layer; hand-copies refused)
    defaults = dict(
            width=1024,
            height=1024,
            steps=30,
            sampler='er_sde',
            scheduler='simple',
            cfg=4.0,
        )
    # the CASCADE GATE (image-edit rework 2026-09-05) — this lane
    # ships a single ComfyUI UNETLoader configuration. The cell states
    # the TRUE quant tier the loader reads (no tier switch today); a
    # future second cell row lands as a real tier (the family grows).
    variants = (
        Variant(id='standard', label='Standard', route='anima', cells=(
            Cell(quant=Quant.F32, label='F32', route='anima', vram_peak_gb=20.0),
        )),
    )


    # loader stack — the weight facts the card renderer reads (the
    # unet basename stated ONCE; no artifact row exists for it)
    lane_inputs = LaneInputs(
        unet='anima-base-v1.0.safetensors',
        text_encoder='qwen_3_06b_base.safetensors',
        clip_type=ClipType.STABLE_DIFFUSION,
        vae='qwen_image_vae.safetensors',
        latent_node='EmptyLatentImage',
    )

    # the image-gen card surface (row 3, 2026-09-06 — the one family
    # whose latent node differs: EmptyLatentImage, matching its
    # template and its lane_inputs row; sampler/encode targets shared
    # with krea-2/z-image).
    card_knobs = (
        KnobRow(card='prompt', inject='CLIPTextEncode.0.text', kind='s'),
        KnobRow(card='negative_prompt', inject='CLIPTextEncode.1.text', kind='s'),
        KnobRow(card='width', inject='EmptyLatentImage.0.width', kind='n'),
        KnobRow(card='height', inject='EmptyLatentImage.0.height', kind='n'),
        KnobRow(card='seed', inject='KSampler.0.seed', kind='n'),
        KnobRow(card='steps', inject='KSampler.0.steps', kind='n'),
        KnobRow(card='cfg', inject='KSampler.0.cfg', kind='n'),
        KnobRow(card='sampler', inject='KSampler.0.sampler_name', kind='s'),
        KnobRow(card='scheduler', inject='KSampler.0.scheduler', kind='s'),
    )
